import React, { useState } from 'react';
import './ReviewModal.css';

const ReviewModal = ({ order, onClose }) => {
  const [rating, setRating] = useState(0);
  const [text, setText] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();

    // ⛔️ пока без API — просто мок
    const newReview = {
      tourId: order.tourId,
      rating,
      text,
      createdAt: new Date().toISOString()
    };

    console.log('Отзыв отправлен:', newReview);

    onClose();
  };

  return (
    <div className="review-modal__overlay">
      <div className="review-modal">
        <button
          className="review-modal__close"
          onClick={onClose}
          aria-label="Закрыть"
        >
          ×
        </button>

        <h2 className="review-modal__title">
          Оставить отзыв
        </h2>

        <p className="review-modal__subtitle">
          Экскурсия: <strong>{order.title}</strong>
        </p>

        <form onSubmit={handleSubmit} className="review-form">
          {/* RATING */}
          <div className="review-form__rating">
            <span>Оценка:</span>

            <div className="stars">
              {[1, 2, 3, 4, 5].map((star) => (
                <button
                  type="button"
                  key={star}
                  className={`star ${rating >= star ? 'active' : ''}`}
                  onClick={() => setRating(star)}
                >
                  ★
                </button>
              ))}
            </div>
          </div>

          {/* TEXT */}
          <textarea
            className="review-form__textarea"
            placeholder="Напишите ваш отзыв..."
            value={text}
            onChange={(e) => setText(e.target.value)}
            required
          />

          <button
            type="submit"
            className="review-form__submit"
            disabled={rating === 0}
          >
            Отправить отзыв
          </button>
        </form>
      </div>
    </div>
  );
};

export default ReviewModal;
